    // Wizard NPC texture 16x22
    const gwiz = mk();
    // Robe / Body (Dark purple)
    pR(gwiz, 4, 8, 8, 12, 0x5B21B6); pR(gwiz, 3, 10, 10, 10, 0x4C1D95);
