    pR(gwiz, 4, 3, 8, 2, 0x7C3AED); pR(gwiz, 5, 1, 6, 2, 0x6D28D9); pR(gwiz, 6, 0, 4, 1, 0x8B5CF6);
    pR(gwiz, 7, 2, 2, 2, 0xF59E0B);
    // Staff & Glowing Orb
